function v32MakeRandomEvent(){
  if(!career)return null;
  career.v30=career.v30||{usedKeys:{},decline:{streak:0,active:false,rescue:0,stage:0},eventPerSeason:0};
  const used=career.v30.usedKeys=career.v30.usedKeys||{};
  const avail=V32_EXTRA_EVENTS.map((e,i)=>({e,i})).filter(x=>!used[`v32ev:${x.i}`]);
  if(!avail.length)return null;
  const idx=v32Seed(`${career.playerId}-${career.seasonNo}-${career.games}-v32`)%avail.length;
  const hit=avail[idx];
  used[`v32ev:${hit.i}`]=1;
  return Object.assign({},hit.e,{_v32Event:true,_event:true,_longArc:true,_season:career.seasonNo});
}
/* 包装 maybeStory：已解锁玩家也走随机事件（与专属剧情并行） */
const __v32MaybeStory=maybeStory;
maybeStory=function(){
  const hit=__v32MaybeStory();
  if(hit)return true;                        /* 专属剧情优先 */
  if(!v32Has()||career.retired)return false;
  if(!career.exclusive)return false;         /* 未解锁：原逻辑已处理随机事件 */
  if(career.stage!=='regular'||ui.storyEvent||ui.modal)return false;
  if(career.games<16)return false;
  const per=(career.v30&&career.v30.eventPerSeason)||0;
  const target=per===0?18:per===1?52:999;
  if(career.games<target)return false;
  const ev=v32MakeRandomEvent();
  if(!ev)return false;
  career.v30.eventPerSeason=per+1;
  stopSim();ui.storyEvent=ev;save();render();return true;
};
/* 随机事件选择结算 */
const __v32StoryChoice=storyChoice;
storyChoice=function(i){
  const raw=ui.storyEvent,isV32=!!(raw&&raw._v32Event);
  const quality=(isV32&&raw.c&&raw.c[i])?raw.c[i][3]:null;
  __v32StoryChoice(i);
  if(!isV32||!v32Has())return;
  career.v30=career.v30||{};
  const d=career.v30.decline=career.v30.decline||{streak:0,active:false,rescue:0,stage:0};
  if(quality==='bad'){
    d.streak=(d.streak||0)+1;
    career.feed.unshift(`赛季事件「${raw.t}」：你选了“${raw.c[i][0]}”，状态出现波动。`);
    if(d.streak>=3&&!d.active){
      d.active=true;d.rescue=2;d.stage=0;
      career.feed.unshift('你连续做出不利选择，生涯进入下滑通道。');
      if(typeof window.v222Pop==='function')window.v222Pop('生涯警报 · 进入下滑通道',`连续 ${d.streak} 次判断失误。还有 2 个赛季可以救回来。`);
    }
  }else if(quality==='good'){
    d.streak=0;
    career.feed.unshift(`赛季事件「${raw.t}」：你选了“${raw.c[i][0]}”，状态稳住了。`);
    if(d.active){d.active=false;d.rescue=0;d.stage=0;career.feed.unshift('你止住了下滑，重新回到稳定轨道。')}
  }
  save();
};

