function v32EraKey(year){
  const y=year||(career&&career.draftYear)||2001;
  if(y<=2003)return'2001';
  if(y<=2009)return'2007';
  if(y<=2014)return'2013';
  if(y<=2016)return'2016';
  if(y<=2025)return'2017';
  return'2026plus';
}
