const V32_FAKE_LAST=['Knox','Rivers','Price','Grant','Mercer','Cole','Cross','Reed','Stone','Bryant','Hayes','Boone','Vance','Ellis','Frost','Nash','Quinn','Rhodes','Slater','Vaughn'];
function v32FakeName(seed){return `${v32Pick(seed+'f',V32_FAKE_FIRST)} ${v32Pick(seed+'l',V32_FAKE_LAST)}`}
function v32MakePlayer(name,team,age,seedStr,peakNow){
  /* 名字清洗：任何拼进名单的坏字符串（undefined/NaN）都不该出现在球员名里 */
  let nm=String(name==null?'':name).replace(/undefined|NaN|null/g,'').trim();
  if(!nm)nm='球员'+(Math.abs(v32Seed(seedStr||'x'))%900+100);
  const s=v32Seed(seedStr+nm);
  const a=age==null?(s%12)+20:age;
  const peak=72+(s%23);                     /* 生涯巅峰档：72~94 */
  const pot=Math.min(99,peak+2+(s%5));
  /* 入行评分按年龄给：新秀离巅峰还差一大截（成长期才有意义），
     24 岁后基本到档；开档联盟（peakNow）直接用巅峰档，免得 2002 年的奥尼尔变成 78。 */
  let ovr=peak;
  if(!peakNow){
    const gap=a<=20?8+(s>>4)%9:a<=23?4+(s>>4)%6:a<=26?(s>>4)%4:0;
    /* 新秀入行上限：19~20 岁不超过 84、21~22 岁不超过 87，
       否则会出现「19 岁新秀直接 91 分」这种不合理起点。 */
    const cap=a<=20?84:a<=22?87:99;
    ovr=Math.min(cap,Math.max(58,peak-gap));
  }
  return{name:nm,team,age:a,potential:pot,ovr,retired:false};
}
