function v32BuildLeague(eraKey,year){
  const roster=V32_ROSTER[eraKey]||{};
  const out=[];
  teams.forEach(t=>{
    const names=roster[t.abbr]&&roster[t.abbr].length?roster[t.abbr]:null;
    for(let i=0;i<9;i++){
      let nm;
      if(names&&names[i])nm=names[i];
      else nm=v32FakeName(`${eraKey}-${t.abbr}-${i}-v32`);
      const realAge=(V32_REAL_AGE[eraKey]||{})[nm];
      const age=realAge!=null?realAge+(year-Number(eraKey)):(21+i);
      out.push(v32MakePlayer(nm,t.abbr,Math.max(19,Math.min(42,age)),`${eraKey}-${t.abbr}-${i}`,true));
    }
  });
  return out;
}
function v32BuildVirtualLeague(year){
  /* 2026+ 开档没有真实名单：用英文虚拟名。
     英文名同样只作为虚构身份使用；中文名不再用于 2026+ 联盟。 */
  const out=[],used={};
  teams.forEach(t=>{for(let i=0;i<9;i++){
    const nm=v180EnglishName(year,t.abbr.charCodeAt(0)*9+i,used);
    used[nm]=1;
    const p=v32MakePlayer(nm,t.abbr,20+i,`${year}-${t.abbr}-${i}`,true);
    p.v180English=true;
    out.push(p);
  }});
  return out;
}
function v32InitLeague(){
  if(!career)return;
  if(career.v32League&&career.v32League.players&&career.v32League.players.length)return;
  const eraKey=v32EraKey(career.draftYear);
  const basePlayers=eraKey==='2026plus'?v32BuildVirtualLeague(career.draftYear):v32BuildLeague(eraKey,Number(eraKey));
  const players=window.v153OpeningLeague?v153OpeningLeague(basePlayers,career):basePlayers;
  career.v32League={eraKey,players,lastYear:career.seasonYear,retired:[],rookies:[]};
  save();
}
