function v180EnglishName(year,i,used){
  const s=Math.abs(v32Seed(String(year)+'-en-'+i))||0;
  const has=nm=>used&&(typeof used.has==='function'?used.has(nm):!!used[nm]);
  for(let k=0;k<500;k++){
    const a=(s+k*7)%V180_FIRST.length;
    const b=(s+k*13+Math.floor(k/V180_FIRST.length))%V180_LAST.length;
    const nm=V180_FIRST[a]+' '+V180_LAST[b];
    if(!has(nm))return nm;
  }
  return 'Player '+String(year).slice(-2)+'-'+(i+1);
}
window.v180EnglishName=v180EnglishName;
function v100VirtualName(year,i,used){
  const s=Math.abs(v32Seed(year+'-virt-'+i))||0;
  for(let k=0;k<24;k++){
    const a=Math.abs(s+k*7)%V100_SUR.length, b=Math.abs(s>>(5+(k%20)))%V100_GIV.length;
    const nm=(V100_SUR[a]||'王')+(V100_GIV[b]||'伟');
    if(!used||!used[nm])return nm;
  }
  return '\u738b'+(10+(Math.abs(i)%89));
}
function v32AdvanceLeague(){
  if(!career||!career.v32League)return;
  const L=career.v32League,year=career.seasonYear;
  if(L.lastYear===year)return;
  L.lastYear=year;
  const retired=[],rookies=[];
  L.players.forEach(p=>{
    const s=v32Seed(`${p.name}-${year}`);
    /* 成长期 / 巅峰期 / 衰退期：
       19–21 岁：涨 2~3；22–25 岁：涨 1~2；26–29 岁：偶尔涨 1（巅峰）；
       30 岁起：跌 1；35 岁起：跌 2；38 岁起：跌 2~3。 */
    if(p.age<22){const room=Math.max(0,p.potential-p.ovr);if(room>0)p.ovr=Math.min(p.potential,p.ovr+2+(s%2))}
    else if(p.age<26){const room=Math.max(0,p.potential-p.ovr);if(room>0)p.ovr=Math.min(p.potential,p.ovr+1+(s%2))}
    else if(p.age<30){if(s%3===0&&p.ovr<p.potential)p.ovr=Math.min(p.potential,p.ovr+1)}
    else{const drop=1+(p.age>=35?1:0)+((p.age>=38&&s%2===0)?1:0);p.ovr=Math.max(45,p.ovr-drop)}
    p.age++;
    if(p.age>=39||(p.ovr<62&&p.age>=33)){p.retired=true;retired.push(p)}
  });
  L.players=L.players.filter(p=>!p.retired);
  /* 每年一整轮真实名单（2001–2025），2026+ 用中文虚拟名 */
  const cls=V100_DRAFT[String(year)]||V32_DRAFT_CLASSES[String(year)]||null;
  const TARGET=teams.length*9;                       /* 270 */
  const shortage=Math.max(0,TARGET-L.players.length);
  /* 有真实名单的年份：补员上限贴着名单长度，尽量少用虚拟名；
     2026+ 没有真实名单时才放开到 34。 */
  const cap=cls?Math.min(30,cls.length+2):30;
  const need=Math.max(8,Math.min(cap,retired.length+shortage));
  /* 每次把新秀发给「当前人最少的队」：原实现是随机扔给某一队，
     结果有的队 4 个人、有的队 16 个人（实测 18 季后联盟 270→119 人）。 */
  const have={},used={};
  L.players.forEach(p=>{if(p&&p.team)have[p.team]=(have[p.team]||0)+1;if(p&&p.name)used[p.name]=1});
  for(let i=0;i<need;i++){
    let virtual=false;
    let nm=cls&&cls[i]?cls[i]:null;
    if(!nm||used[nm]){nm=v180EnglishName(year,i,used);virtual=true;}
    used[nm]=1;
    let t=null,bestN=1e9;
    teams.forEach(tm=>{const n=have[tm.abbr]||0;
      if(n<bestN||(n===bestN&&(v32Seed(year+tm.abbr+i)%2===0))){bestN=n;t=tm.abbr}});
    have[t]=(have[t]||0)+1;
    const p=v32MakePlayer(nm,t,19+(v32Seed(nm+year)%3),`${year}-rookie-${i}`);
    p.rookie=true;if(!(cls&&cls[i]))p.gen=true;
    if(virtual){p.v180English=true;p.realName='draft:'+year+':'+i;}
    L.players.push(p);rookies.push(p);
  }
  L.retired=L.retired.concat(retired).slice(-60);
  L.rookies=rookies;
  v32RecalcPower();
  save();
}
function v32RecalcPower(){
  if(!career||!career.v32League)return;
  const byTeam={};
  career.v32League.players.forEach(p=>{(byTeam[p.team]=byTeam[p.team]||[]).push(p.ovr)});
  teams.forEach(t=>{
    const arr=(byTeam[t.abbr]||[]).slice().sort((a,b)=>b-a);
    if(!arr.length)return;
    const top=arr.slice(0,9);
    const avg=top.reduce((a,b)=>a+b,0)/top.length;
    t.power=v32Clamp(Math.round(avg*0.92+8),60,99);
  });
}
function v32LeagueStars(year,count){
  v32InitLeague();
  if(!career||!career.v32League)return[];
  return career.v32League.players.slice().sort((a,b)=>b.ovr-a.ovr||a.age-b.age).slice(0,count||15);
}
